package com.yuegang.zhihui.product.application;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.product.api.*;import java.sql.*;import java.time.ZoneOffset;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class CatalogService{private final JdbcTemplate jdbc;private final ObjectMapper json;public CatalogService(DataSource d,ObjectMapper j){jdbc=new JdbcTemplate(d);json=j;}public CategoryView createCategory(SaveCategoryRequest r){long id=next();jdbc.update("INSERT INTO product_category(id,parent_id,code,name,sort_order) VALUES(?,?,?,?,?)",id,optional(r.parentId()),r.code(),r.name(),r.sortOrder());return category(id);}public List<CategoryView>categories(boolean enabled){return jdbc.query("SELECT * FROM product_category"+(enabled?" WHERE enabled=TRUE":"")+" ORDER BY parent_id,sort_order,id",(r,n)->mapCategory(r));}public BrandView createBrand(SaveBrandRequest r){long id=next();jdbc.update("INSERT INTO product_brand(id,code,name,logo_url) VALUES(?,?,?,?)",id,r.code(),r.name(),r.logoUrl());return brand(id);}public List<BrandView>brands(boolean enabled){return jdbc.query("SELECT * FROM product_brand"+(enabled?" WHERE enabled=TRUE":"")+" ORDER BY name,id",(r,n)->mapBrand(r));}public TraceEventView addTrace(String sku,TraceEventRequest r){long id=next(),skuId=positive(sku);jdbc.update("INSERT INTO product_trace_event(id,sku_id,event_type,location_name,occurred_at,details_json) VALUES(?,?,?,?,?,?)",id,skuId,r.type(),r.location(),Timestamp.from(r.occurredAt().toInstant()),write(r.details()));return new TraceEventView(Long.toString(id),sku,r.type(),r.location(),r.occurredAt(),r.details());}public List<TraceEventView>trace(String sku){return jdbc.query("SELECT * FROM product_trace_event WHERE sku_id=? ORDER BY occurred_at",(r,n)->new TraceEventView(Long.toString(r.getLong("id")),Long.toString(r.getLong("sku_id")),r.getString("event_type"),r.getString("location_name"),r.getTimestamp("occurred_at").toInstant().atOffset(ZoneOffset.UTC),read(r.getString("details_json"))),positive(sku));}private CategoryView category(long id){return jdbc.query("SELECT * FROM product_category WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return mapCategory(r);},id);}private BrandView brand(long id){return jdbc.query("SELECT * FROM product_brand WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return mapBrand(r);},id);}private static CategoryView mapCategory(ResultSet r)throws SQLException{Object p=r.getObject("parent_id");return new CategoryView(Long.toString(r.getLong("id")),p==null?null:p.toString(),r.getString("code"),r.getString("name"),r.getInt("sort_order"),r.getBoolean("enabled"),r.getLong("version"));}private static BrandView mapBrand(ResultSet r)throws SQLException{return new BrandView(Long.toString(r.getLong("id")),r.getString("code"),r.getString("name"),r.getString("logo_url"),r.getBoolean("enabled"),r.getLong("version"));}private String write(Object x){try{return json.writeValueAsString(x==null?Map.of():x);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private Map<String,Object>read(String x){try{return x==null?Map.of():json.readValue(x,new TypeReference<>(){});}catch(Exception e){return Map.of();}}private static Long optional(String x){return x==null||x.isBlank()?null:positive(x);}private static long positive(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
